"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[84967],{84967:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<TvCard\\n  cover=\\"/assets/snippets/screen/LadyDua2026.jpg\\"\\n  title=\\"레이디 두아 (2026)\\"\\n  release_date=\\"2026-02-13\\"\\n  episode_count=8\\n  genres=[\\"미스터리\\"]\\n  rating=4\\n  tags=\\"tv\\"\\n/>\\n</center>\\n\\n## Review\\n`레이디 두아(Lady Dua)`는 가짜일지라도 완벽한 명품이 되고 싶었던 여자와 그녀가 쥔 진실을 집요하게 쫓는 형사의 쫓고 쫓기는 서스펜스를 그린 스릴러 작품이다.  \\n\\n현대인들의 내면에 숨겨진 <mark>허영과 욕망</mark>을 이용하여 `진실`에 대한 묵직한 질문을 날카롭게 파고들었다.  \\n\\n진실을 파헤칠수록 그녀의 정체가 서서히 드러나며, 그 과정에서 나타나는 인물들의 욕망과 심리가 흥미롭다.  \\n타깃이 무엇을 원하는지를 정확히 알고 그것을 이용하여 자신의 목적을 달성하는 그녀의 모습이 인상적이다.  \\n\\n조금씩 확장되는 인물들의 관계와 그들이 얽혀 마지막에 하나의 진실로 귀결되는 과정이 좋았다.  \\n\\n모든 것을 철두철미하게 계획하는 그녀도 어느 한 인간의 광기는 예상하지 못해 흔들리는 모습이 나온다.  \\n\\n마지막 그녀의 선택은 그녀가 진정으로 자신의 브랜드를 사랑하는지, 아니면 자신의 욕망을 위해 브랜드를 이용한 것인지에 대한 답을 보여준다.  \\n\\n주인공들의 연기력이 압도적이었다.  \\n신혜선은 속을 도통 알 수 없는 매혹적이면서도 위험한 인물의 내면을 완벽하게 소화해 냈고, 이준혁 역시 그녀를 맹렬히 추적하면서도 혼란에 빠지는 입체적인 연기를 보여주었다.\\n\\n`나서는 피해자가 없는데 사기죄가 되나요?`  \\n`진짜와 구별할 수 없는데 가짜라고 볼 수 있나요?`"}')}}]);